1	package posemap
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"fmt"
7		"sort"
8	)
9	
10	// Invalidate 提交一次路标失效操作：req.ID 与 req.Reason 必须非空；
11	// req.Landmarks 必须是非空、无重复的路标标识集合，且每个路标当前都必须
12	// 存在一条仍有效的出现记录。满足时，这些当前有效记录同时失效，失效时间
13	// 取提交时的当前位姿时间；位姿与已接受的观测均不删除，路标只是不再被
14	// 当作当前有效路标（区域查询立即排除）。
15	//
16	// 成功时返回失效时间与每个路标的标识及被失效记录的出现编号（按标识
17	// 排序）。操作标识/原因为空、列表为空、路标标识为空或重复、路标不存在
18	// 或当前已失效时，以可区分的 *RejectError 整次拒绝，不留下任何部分
19	// 变化。
20	//
21	// 同一操作标识以相同原因与相同路标集合重复提交时，直接返回首次结果，
22	// 即使这些路标后来又再次出现也不会再次撤下它们；同一标识对应不同内容
23	// （原因或集合不同）则明确拒绝。
24	func (m *Map) Invalidate(req Invalidation) (InvalidationResult, error) {
25		m.mu.Lock()
26		defer m.mu.Unlock()
27		if m.closed {
28			return InvalidationResult{}, ErrClosed
29		}
30		st := m.state
31	
32		// 已保存的失效操作：相同内容直接返回首次结果；不同内容明确拒绝。
33		// 不做任何校验或状态变更，即使其后路标又再次出现。
34		setHash := landmarkSetHash(req.Landmarks)
35		if rec, ok := st.invalIndex[req.ID]; ok {
36			if rec.reason == req.Reason && rec.hash == setHash {
37				return cloneInvalidationResult(rec.result), nil
38			}
39			return InvalidationResult{}, &RejectError{Kind: RejectInvalidationMismatch, Landmark: req.ID, HasLandmark: true}
40		}
41	
42		if req.ID == "" {
43			return InvalidationResult{}, &RejectError{Kind: RejectEmptyID}
44		}
45		if req.Reason == "" {
46			return InvalidationResult{}, &RejectError{Kind: RejectEmptyReason}
47		}
48		if len(req.Landmarks) == 0 {
49			return InvalidationResult{}, &RejectError{Kind: RejectEmptyLandmarkList}
50		}
51	
52		// 先校验集合本身：标识非空、无重复；再校验每个路标当前存在有效记录。
53		seen := make(map[string]struct{}, len(req.Landmarks))
54		for _, id := range req.Landmarks {
55			if id == "" {
56				return InvalidationResult{}, &RejectError{Kind: RejectEmptyID}
57			}
58			if _, dup := seen[id]; dup {
59				return InvalidationResult{}, &RejectError{Kind: RejectDuplicateLandmarkEntry, Landmark: id, HasLandmark: true}
60			}
61			seen[id] = struct{}{}
62		}
63		for _, id := range req.Landmarks {
64			lm, ok := st.landmarks[id]
65			if !ok {
66				return InvalidationResult{}, &RejectError{Kind: RejectLandmarkNotFound, Landmark: id, HasLandmark: true}
67			}
68			if lm.activeOccurrence() == nil {
69				return InvalidationResult{}, &RejectError{Kind: RejectLandmarkInactive, Landmark: id, HasLandmark: true}
70			}
71		}
72	
73		// ---- 全部校验通过：对当前有效记录同时标记失效并落盘 ----
74		invalidTime := st.trajectory[len(st.trajectory)-1].Time
75		ids := append([]string(nil), req.Landmarks...)
76		sort.Strings(ids)
77		res := InvalidationResult{
78			Time:      invalidTime,
79			Landmarks: make([]InvalidatedLandmark, 0, len(ids)),
80		}
81		invalidated := make([]*occurrenceState, 0, len(ids))
82		for _, id := range ids {
83			lm := st.landmarks[id]
84			occ := lm.activeOccurrence()
85			invalidated = append(invalidated, occ)
86			res.Landmarks = append(res.Landmarks, InvalidatedLandmark{ID: id, Occurrence: len(lm.appearances)})
87			occ.active = false
88			occ.invalidTime = invalidTime
89			occ.invalidReason = req.Reason
90			occ.invalidOpID = req.ID
91		}
92		rec := &invalidationRecord{
93			id:     req.ID,
94			reason: req.Reason,
95			hash:   setHash,
96			result: cloneInvalidationResult(res),
97		}
98		invalLenBefore := len(st.invalRecords)
99		st.invalRecords = append(st.invalRecords, rec)
100		st.invalIndex[req.ID] = rec
101	
102		if err := m.saveReplace(); err != nil {
103			for _, occ := range invalidated {
104				occ.active = true
105				occ.invalidTime = 0
106				occ.invalidReason = ""
107				occ.invalidOpID = ""
108			}
109			st.invalRecords = st.invalRecords[:invalLenBefore]
110			delete(st.invalIndex, req.ID)
111			return InvalidationResult{}, err
112		}
113		return res, nil
114	}
115	
116	// LandmarkAppearances 按出现编号递增返回同一标识的历次出现记录：每次的
117	// 位置、观测计数、是否仍为当前有效记录、首次观测时间，以及失效时间与
118	// 原因。仍有效的出现明确不携带失效信息（Appearance.Active 为真）；旧
119	// 文件中的第 1 次出现缺少逐帧来源，HasFirstSeen 为假，首次观测时间
120	// 未知。标识从未出现时返回可 errors.Is(ErrLandmarkNotFound) 区分的
121	// 未找到结果。
122	func (m *Map) LandmarkAppearances(id string) (LandmarkHistory, error) {
123		m.mu.Lock()
124		defer m.mu.Unlock()
125		if m.closed {
126			return LandmarkHistory{}, ErrClosed
127		}
128		lm, ok := m.state.landmarks[id]
129		if !ok {
130			return LandmarkHistory{}, fmt.Errorf("%w: %s", ErrLandmarkNotFound, id)
131		}
132		h := LandmarkHistory{ID: id, Appearances: make([]Appearance, 0, len(lm.appearances))}
133		for i, occ := range lm.appearances {
134			ap := Appearance{
135				Number:        i + 1,
136				Landmark:      Landmark{ID: id, X: occ.x, Y: occ.y, Count: occ.count},
137				Active:        occ.active,
138				FirstSeenTime: occ.firstSeenTime,
139				HasFirstSeen:  occ.hasFirstSeen,
140			}
141			if !occ.active {
142				ap.InvalidTime = occ.invalidTime
143				ap.InvalidReason = occ.invalidReason
144				ap.InvalidOpID = occ.invalidOpID
145			}
146			h.Appearances = append(h.Appearances, ap)
147		}
148		return h, nil
149	}
150	
151	func cloneInvalidationResult(r InvalidationResult) InvalidationResult {
152		lms := make([]InvalidatedLandmark, len(r.Landmarks))
153		copy(lms, r.Landmarks)
154		r.Landmarks = lms
155		return r
156	}
157	
158	// landmarkSetHash 计算一个路标标识集合的确定性指纹，用于同一失效操作
159	// 标识的重复内容判定，与输入次序无关（集合语义）。
160	func landmarkSetHash(ids []string) string {
161		sorted := append([]string(nil), ids...)
162		sort.Strings(sorted)
163		h := sha256.New()
164		var lenBuf [4]byte
165		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(sorted)))
166		h.Write(lenBuf[:])
167		for _, s := range sorted {
168			binary.BigEndian.PutUint32(lenBuf[:], uint32(len(s)))
169			h.Write(lenBuf[:])
170			h.Write([]byte(s))
171		}
172		return fmt.Sprintf("%x", h.Sum(nil))
173	}
