1137	func finitePose(p Pose) bool {
1138		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
1139	}
1140	
1141	// geomTol 是打开时核对校正记录几何一致性的相对容差（另含 1 的绝对项）。
1142	const geomTol = 1e-9
1143	
1144	// coordClose 判断保存坐标 got 是否在容许误差内等于期望 want：误差不得
1145	// 超过 geomTol 乘以 1、|want|、|got| 三者中的最大值。参与比较的值都已
1146	// 校验为有限，差值必有限，NaN 不会混入并被误当相等。
1147	func coordClose(got, want float64) bool {
1148		scale := math.Max(1, math.Max(math.Abs(want), math.Abs(got)))
1149		return math.Abs(got-want) <= geomTol*scale
1150	}
1151	
1152	// angleClose 按最短角度差判断两个角度是否相等，容差 geomTol 弧度。两个
1153	// 角度都已校验为有限；差值经归一化到 [-π,π) 即最短角度差，正确处理
1154	// ±π 附近跨边界但物理方向相同的情形。
1155	func angleClose(got, want float64) bool {
1156		return math.Abs(normalizeAngle(got-want)) <= geomTol
1157	}
1158	
1159	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
1160	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
1161	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
1162		h := sha256.New()
1163		var b [8]byte
1164		binary.BigEndian.PutUint64(b[:], uint64(anchor))
1165		h.Write(b[:])
1166		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
1167			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
1168			h.Write(b[:])
1169		}
1170		return fmt.Sprintf("%x", h.Sum(nil))
1171	}
1172	
1173	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
1174	func (m *Map) saveExclusive() error {
1175		data, err := encodeFile(m.state)
1176		if err != nil {
1177			return err
1178		}
1179		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
1180		if err != nil {
1181			return err
1182		}
1183		return writeAndClose(f, data, m.path)
1184	}
1185	
1186	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
1187	func (m *Map) saveReplace() (err error) {
1188		data, err := encodeFile(m.state)
1189		if err != nil {
1190			return err
1191		}
1192		dir, base := filepath.Split(m.path)
1193		if dir == "" {
1194			dir = "."
1195		}
1196		f, err := os.CreateTemp(dir, base+".tmp-*")
1197		if err != nil {
1198			return err
1199		}
1200		tmpName := f.Name()
1201		// 任何失败路径都尽力清理临时文件。
1202		defer func() {
1203			if err != nil {
1204				_ = os.Remove(tmpName)
1205			}
1206		}()
1207		if err = writeAndClose(f, data, tmpName); err != nil {
1208			return err
1209		}
1210		if err = os.Rename(tmpName, m.path); err != nil {
1211			return err
1212		}
1213		return nil
1214	}
1215	
1216	func writeAndClose(f *os.File, data []byte, name string) (err error) {
1217		defer func() {
1218			if cerr := f.Close(); err == nil {
1219				err = cerr
1220			}
1221		}()
1222		if _, err = f.Write(data); err != nil {
1223			return err
1224		}
1225		if err = f.Sync(); err != nil {
1226			return err
1227		}
1228		return nil
1229	}
1230	
1231	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
1232	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
1233	func canonicalHash(frames []Frame) string {
1234		h := sha256.New()
1235		var lenBuf [4]byte
1236		var numBuf [8]byte
1237		putU32 := func(v uint32) {
1238			binary.BigEndian.PutUint32(lenBuf[:], v)
1239			h.Write(lenBuf[:])
1240		}
1241		putU64 := func(v uint64) {
1242			binary.BigEndian.PutUint64(numBuf[:], v)
1243			h.Write(numBuf[:])
1244		}
1245		putStr := func(s string) {
1246			putU32(uint32(len(s)))
1247			h.Write([]byte(s))
1248		}
1249	
1250		putU32(uint32(len(frames)))
1251		for _, fr := range frames {
1252			putU64(uint64(fr.Time))
1253			putU64(math.Float64bits(fr.DX))
1254			putU64(math.Float64bits(fr.DY))
1255			putU64(math.Float64bits(fr.DHeading))
1256			putU64(math.Float64bits(fr.MoveVariance))
1257			putU32(uint32(len(fr.Observations)))
1258			for _, ob := range fr.Observations {
1259				putStr(ob.ID)
1260				putU64(math.Float64bits(ob.X))
1261				putU64(math.Float64bits(ob.Y))
1262			}
1263		}
1264		return fmt.Sprintf("%x", h.Sum(nil))
1265	}
1266

