248					iv.Landmarks = kept
249				},
250			},
251			{
252				name:    "operation moved onto later occurrence orphans old one",
253				builder: buildInvalidationMap,
254				mutate: func(fd *fileData) {
255					// 把 A 对 L 的失效从第 1 次出现整体搬到第 2 次：A 记录时间
256					// 改为 300 并指向 occ2，occ2 被填成与 A 完全一致的失效信息，
257					// M 的失效时间同步改为 300。轨迹、出现次序、观测归属与计数
258					// 仍然成立，且每条失效记录正向都能对上等三要素的出现——唯独
259					// occ1 仍标记着 A@200 却没有任何操作条目引用，必须由反向
260					// 核对拒绝，不能把旧结果顺势指向最新记录。
261					iv := &fd.Invalidations[0]
262					iv.Time = 300
263					iv.Landmarks[invalEntryIndex(iv, "L")].Occurrence = 2
264					iL := landmarkIndex(fd, "L")
265					occ2 := &fd.Landmarks[iL].Occurrences[1]
266					occ2.Active = false
267					occ2.InvalidTime = 300
268					occ2.InvalidReason = "gone"
269					occ2.InvalidOpID = "A"
270					iM := landmarkIndex(fd, "M")
271					fd.Landmarks[iM].Occurrences[0].InvalidTime = 300
272				},
273			},
274		}
275		for _, tc := range cases {
276			t.Run(tc.name, func(t *testing.T) {
277				path := filepath.Join(t.TempDir(), "m.pose")
278				tc.builder(t, path)
279				fd := readFileData(t, path)
280				tc.mutate(&fd)
281				writeFileDataRaw(t, path, &fd)
282	
283				m, err := Open(path)
284				if !errors.Is(err, ErrCorrupt) {
285					t.Fatalf("err = %v, want ErrCorrupt", err)
286				}
287				if m != nil {
288					t.Fatalf("Open returned usable map: %v", m)
289				}
290			})
291		}
292	}
293	
294	// 拒绝打开时原文件内容必须保持不变：不能删掉错误条目、补造出现或改写
295	// 失效信息后继续加载。
296	func TestOpenInvalidationMismatchLeavesFileUntouched(t *testing.T) {
297		path := filepath.Join(t.TempDir(), "m.pose")
298		buildInvalidationMap(t, path)
299		fd := readFileData(t, path)
300		fd.Invalidations[0].Landmarks[invalEntryIndex(&fd.Invalidations[0], "L")].Occurrence = 3
301		writeFileDataRaw(t, path, &fd)
302		saved, err := os.ReadFile(path)
303		if err != nil {
304			t.Fatal(err)
305		}
306	
307		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
308			t.Fatalf("err = %v, want ErrCorrupt, map=%v", err, m)
309		}
310		got, err := os.ReadFile(path)
311		if err != nil {
312			t.Fatal(err)
313		}
314		if string(got) != string(saved) {
315			t.Fatal("Open modified the rejected file")
316		}
317	}
318	
319	// 兼容没有失效记录的旧地图：平铺保存的路标仍视为第 1 次有效出现，旧路标
320	// 缺少首次观测时间不会单独导致这项检查失败。
321	func TestOpenLegacyFileWithoutInvalidations(t *testing.T) {
322		path := filepath.Join(t.TempDir(), "old.pose")
323		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
324		m, err := Create(path, cfg)
325		if err != nil {
326			t.Fatal(err)
327		}
328		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
329			{Time: 100, Observations: []Observation{{ID: "L", X: 1}, {ID: "M", X: 2}}},
330			{Time: 200, Observations: []Observation{{ID: "L", X: 1}}},
331		}}); err != nil {
332			t.Fatal(err)
333		}
334		writeLegacyV1File(t, path, m.state)
335		if err := m.Close(); err != nil {
336			t.Fatal(err)
337		}
338	
339		m2, err := Open(path)
340		if err != nil {
341			t.Fatalf("open legacy file: %v", err)
342		}
343		defer m2.Close()
344		h, err := m2.LandmarkAppearances("L")
345		if err != nil {
346			t.Fatal(err)
347		}
348		if len(h.Appearances) != 1 || !h.Appearances[0].Active || h.Appearances[0].HasFirstSeen {
349			t.Fatalf("legacy L = %+v", h.Appearances)
350		}
351		if lms := activeLandmarks(t, m2); len(lms) != 2 {
352			t.Fatalf("legacy active landmarks = %+v", lms)
353		}
354	}
355	
356	// 旧地图后来产生的失效操作也要检查对应关系，但不要求补齐原本缺失的逐帧
357	// 观测：合法的混合文件打开后查询与重复提交结果与保存前一致；篡改交叉
358	// 关系后仍按 ErrCorrupt 拒绝。
359	func TestOpenLegacyFileLaterInvalidationChecked(t *testing.T) {
360		path := filepath.Join(t.TempDir(), "mixed.pose")
361		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
362		m, err := Create(path, cfg)
363		if err != nil {
364			t.Fatal(err)
365		}
366		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
367			{Time: 100, Observations: []Observation{{ID: "L", X: 1}}},
368			{Time: 200, Observations: []Observation{{ID: "L", X: 1}}},
369		}}); err != nil {
370			t.Fatal(err)
371		}
372		writeLegacyV1File(t, path, m.state)
373		m.Close()
374	
375		// 旧路标（第 1 次出现，首次观测时间未知）在 t=200 被失效，t=300 再现。
376		m2, err := Open(path)
377		if err != nil {
378			t.Fatal(err)
379		}
380		first, err := m2.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}})
381		if err != nil {
382			t.Fatalf("invalidate on legacy map: %v", err)
383		}
384		if first.Time != 200 || first.Landmarks[0].Occurrence != 1 {
385			t.Fatalf("first result = %+v", first)
386		}
387		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
388			{Time: 300, DX: 5, Observations: []Observation{{ID: "L"}}},
389		}}); err != nil {
390			t.Fatal(err)
391		}
392		if err := m2.Close(); err != nil {
393			t.Fatal(err)
394		}
395	
396		m3, err := Open(path)
397		if err != nil {
398			t.Fatalf("reopen mixed file: %v", err)
399		}
400		h, _ := m3.LandmarkAppearances("L")
401		if len(h.Appearances) != 2 {
402			t.Fatalf("mixed history = %+v", h.Appearances)
403		}
404		if h.Appearances[0].Active || h.Appearances[0].HasFirstSeen ||
405			h.Appearances[0].InvalidOpID != "op1" || h.Appearances[0].InvalidTime != 200 {
406			t.Fatalf("mixed occ1 = %+v", h.Appearances[0])
407		}
408		if !h.Appearances[1].Active || h.Appearances[1].FirstSeenTime != 300 {
409			t.Fatalf("mixed occ2 = %+v", h.Appearances[1])
410		}
411		// 重复提交 op1 仍返回首次结果，不撤下新出现。
412		again, err := m3.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}})
413		if err != nil || again.Time != first.Time || again.Landmarks[0].Occurrence != 1 {
414			t.Fatalf("resubmit after reopen: %v %+v", err, again)
415		}
416		if h, _ := m3.LandmarkAppearances("L"); !h.Appearances[1].Active {
417			t.Fatal("resubmit re-invalidated the new occurrence")
418		}
419		if err := m3.Close(); err != nil {
420			t.Fatal(err)
421		}
422	
423		// 篡改混合文件中失效记录与旧出现的对应关系：拒绝。
424		fd := readFileData(t, path)
425		fd.Invalidations[0].Time = 250
426		writeFileDataRaw(t, path, &fd)
427		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
428			t.Fatalf("tampered mixed file: err = %v, want ErrCorrupt, map=%v", err, m)
429		}
430	}
